16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.AgeBand;
20	import org.springframework.samples.petclinic.util.CityLocality;
21	import org.springframework.samples.petclinic.util.CustomerCode;
22	import org.springframework.samples.petclinic.util.E164PhoneNumber;
23	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
24	import org.springframework.samples.petclinic.util.RegionTimezone;
25	
26	import jakarta.persistence.*;
27	import jakarta.validation.constraints.NotEmpty;
28	import jakarta.validation.constraints.Pattern;
29	
30	import java.time.LocalDate;
31	import java.time.temporal.ChronoUnit;
32	import java.util.*;
33	
34	/**
35	 * Simple JavaBean domain object representing an owner.
36	 *
37	 * @author Ken Krebs
38	 * @author Juergen Hoeller
39	 * @author Sam Brannen
40	 * @author Michael Isvy
41	 */
42	@Entity
43	@Table(name = "owners")
44	public class Owner extends Person {
45	    @Column(name = "title")
46	    private String title;
47	
48	    @Column(name = "address")
49	    @NotEmpty
50	    private String address;
51	
52	    @Column(name = "address_line1")
53	    private String addressLine1;
54	
55	    @Column(name = "address_line2")
56	    private String addressLine2;
57	
58	    @Column(name = "city")
59	    @NotEmpty
60	    private String city;
61	
62	    @Column(name = "telephone")
63	    @NotEmpty
64	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
65	    private String telephone;
66	
67	    @Column(name = "email")
68	    private String email;
69	
70	    @Column(name = "postcode")
71	    private String postcode;
72	
73	    @Column(name = "registration_date")
74	    private LocalDate registrationDate;
75	
76	    @Column(name = "birth_date")
77	    private LocalDate birthDate;
78	
79	    @Column(name = "customer_code")
80	    private String customerCode;
81	
82	    @Column(name = "household_id")
83	    private String householdId;
84	
85	    @Column(name = "namesake_count")
86	    private Integer namesakeCount;
87	
88	    @Column(name = "household_size")
89	    private Integer householdSize;
90	
91	    @Column(name = "membership_number")
92	    private String membershipNumber;
93	
94	    @Column(name = "bulk_signup_warning", nullable = false)
95	    private boolean bulkSignupWarning;
96	
97	    @Column(name = "possible_duplicate", nullable = false)
98	    private boolean possibleDuplicate;
99	
100	    @Column(name = "possible_duplicate_of")
101	    private Integer possibleDuplicateOf;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    /**
107	     * The owner's personal title (one of MR, MRS, MS or DR), or null when none was
108	     * supplied. Stored verbatim and used to compose the {@link #getSalutation() salutation}.
109	     */
110	    public String getTitle() {
111	        return this.title;
112	    }
113	
114	    public void setTitle(String title) {
115	        this.title = title;
116	    }
117	
118	    /**
119	     * The owner's salutation: the {@link #getTitle() title} and last name separated by a
120	     * space (e.g. {@code "DR Who"}), or just the last name when no title is recorded.
121	     * Derived from stored state, never persisted.
122	     */
123	    public String getSalutation() {
124	        return (this.title == null || this.title.isEmpty())
125	            ? getLastName()
126	            : this.title + " " + getLastName();
127	    }
128	
129	    public String getAddress() {
130	        return this.address;
131	    }
132	
133	    public void setAddress(String address) {
134	        this.address = address;
135	    }
136	
137	    /**
138	     * The first line of the owner's structured address, in normalized form, or null when the
139	     * owner was created from the flat {@link #getAddress() address} only. The composed
140	     * {@code address} is derived from this and {@link #getAddressLine2()}.
141	     */
142	    public String getAddressLine1() {
143	        return this.addressLine1;
144	    }
145	
146	    public void setAddressLine1(String addressLine1) {
147	        this.addressLine1 = addressLine1;
148	    }
149	
150	    /**
151	     * The optional second line of the owner's structured address, in normalized form, or null
152	     * when absent or when the owner was created from the flat {@link #getAddress() address}.
153	     */
154	    public String getAddressLine2() {
155	        return this.addressLine2;
156	    }
157	
158	    public void setAddressLine2(String addressLine2) {
159	        this.addressLine2 = addressLine2;
160	    }
161	
162	    public String getCity() {
163	        return this.city;
164	    }
165	
166	    public void setCity(String city) {
167	        this.city = city;
168	    }
169	
170	    public String getTelephone() {
171	        return this.telephone;
172	    }
173	
174	    public void setTelephone(String telephone) {
175	        this.telephone = telephone;
176	    }
177	
178	    /**
179	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
180	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
181	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
182	     * persisted.
183	     */
184	    public String getTelephoneDisplay() {
185	        return E164PhoneNumber.toDisplay(this.telephone);
186	    }
187	
188	    public String getEmail() {
189	        return this.email;
190	    }
191	
192	    public void setEmail(String email) {
193	        this.email = email;
194	    }
195	
196	    /**
197	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
198	     * against the city's region and then stored verbatim. Optional, so may be null.
199	     */
200	    public String getPostcode() {
201	        return this.postcode;
202	    }
203	
204	    public void setPostcode(String postcode) {
205	        this.postcode = postcode;
206	    }
207	
208	    public LocalDate getRegistrationDate() {
209	        return this.registrationDate;
210	    }
211	
212	    public void setRegistrationDate(LocalDate registrationDate) {
213	        this.registrationDate = registrationDate;
214	    }
215	
216	    /**
217	     * The owner's date of birth. Optional, so may be null.
218	     */
219	    public LocalDate getBirthDate() {
220	        return this.birthDate;
221	    }
222	
223	    public void setBirthDate(LocalDate birthDate) {
224	        this.birthDate = birthDate;
225	    }
226	
227	    /**
228	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
229	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
230	     * birth date against the registration date. Null when no birth date is recorded.
231	     * Derived from stored state, never persisted.
232	     */
233	    public String getAgeBand() {
234	        if (this.birthDate == null || this.registrationDate == null) {
235	            return null;
236	        }
237	        return AgeBand.of(this.birthDate, this.registrationDate);
238	    }
239	
240	    public String getCustomerCode() {
241	        return this.customerCode;
242	    }
243	
244	    public void setCustomerCode(String customerCode) {
245	        this.customerCode = customerCode;
246	    }
247	
248	    /**
249	     * The stable identifier of the household this owner belongs to: the first twelve hex
250	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
251	     * sharing a last name and postcode resolves to the same value. Null when the owner has
252	     * no postcode. Assigned at creation.
253	     */
254	    public String getHouseholdId() {
255	        return this.householdId;
256	    }
257	
258	    public void setHouseholdId(String householdId) {
259	        this.householdId = householdId;
260	    }
261	
262	    public Integer getNamesakeCount() {
263	        return this.namesakeCount;
264	    }
265	
266	    public void setNamesakeCount(Integer namesakeCount) {
267	        this.namesakeCount = namesakeCount;
268	    }
269	
270	    public Integer getHouseholdSize() {
271	        return this.householdSize;
272	    }
273	
274	    public void setHouseholdSize(Integer householdSize) {
275	        this.householdSize = householdSize;
276	    }
277	
278	    public String getMembershipNumber() {
279	        return this.membershipNumber;
280	    }
281	
282	    public void setMembershipNumber(String membershipNumber) {
283	        this.membershipNumber = membershipNumber;
284	    }
285	
286	    /**
287	     * Whether this owner was created as part of a bulk signup: {@code true} when more
288	     * than 80 owners had already been registered on this owner's registration date at
289	     * the moment it was created, {@code false} otherwise. Captured at creation.
290	     */
291	    public boolean isBulkSignupWarning() {
292	        return this.bulkSignupWarning;
293	    }
294	
295	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
296	        this.bulkSignupWarning = bulkSignupWarning;
297	    }
298	
299	    /**
300	     * Whether this owner resembles an existing one: {@code true} when, at creation, it
301	     * shared an existing owner's household (same last name and postcode, hence the same
302	     * {@link #getHouseholdId() household id}) while having a different telephone and was not
303	     * a declared household member, {@code false} otherwise. A declared member (created with
304	     * {@code sharesHousehold}) is a genuine member, not a suspected duplicate. When true,
305	     * {@link #getPossibleDuplicateOf()} holds that owner's id. Captured at creation.
306	     */
307	    public boolean isPossibleDuplicate() {
308	        return this.possibleDuplicate;
309	    }
310	
311	    public void setPossibleDuplicate(boolean possibleDuplicate) {
312	        this.possibleDuplicate = possibleDuplicate;
313	    }
314	
315	    /**
316	     * The id of the existing owner this owner possibly duplicates (same household — last
317	     * name and postcode — different telephone), or null when it is not a possible
318	     * duplicate. Captured at creation.
319	     */
320	    public Integer getPossibleDuplicateOf() {
321	        return this.possibleDuplicateOf;
322	    }
323	
324	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
325	        this.possibleDuplicateOf = possibleDuplicateOf;
326	    }
327	
328	    /**
329	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
330	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
331	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
332	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
333	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
334	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
335	     * region is derived directly from the stored postcode and city. Derived from stored
336	     * state, never persisted.
337	     */
338	    public String getLocality() {
339	        String region = CustomerCode.regionOf(this.customerCode);
340	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
341	    }
342	
343	    /**
344	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
345	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
346	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
347	     * has no known timezone. Derived from stored state, never persisted.
348	     */
349	    public String getTimezone() {
350	        return RegionTimezone.forRegion(getLocality());
351	    }
352	
353	    /**
354	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
355	     * has an email address, gains 1 when this owner had no namesakes at creation
356	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
357	     * members, and gains 3 when this owner's tenure exceeds 365 days. A newly created owner
358	     * has zero tenure, so it never earns those points at creation. Derived from stored
359	     * state, never persisted.
360	     */
361	    public int getMembershipPoints() {
362	        int points = 0;
363	        if (hasEmail()) {
364	            points += 2;
365	        }
366	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
367	            points += 1;
368	        }
369	        if (this.householdSize != null && this.householdSize >= 3) {
370	            points += 2;
371	        }
372	        if (getTenureDays() > 365) {
373	            points += 3;
374	        }
375	        return points;
376	    }
377	
378	    /**
379	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
380	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Derived from
381	     * stored state, never persisted.
382	     */
383	    public int getMembershipLevel() {
384	        int points = getMembershipPoints();
385	        if (points <= 1) {
386	            return 1;
387	        }
388	        if (points <= 3) {
389	            return 2;
390	        }
391	        if (points <= 5) {
392	            return 3;
393	        }
394	        return 4;
395	    }
396	
397	    /**
398	     * The owner's tenure in whole days: the number of days from the {@code registrationDate}
399	     * to the current server date, or 0 when no registration date is recorded. Never negative
400	     * in practice, since a future registration date is rejected at creation.
401	     */
402	    private long getTenureDays() {
403	        if (this.registrationDate == null) {
404	            return 0;
405	        }
406	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
407	    }
408	
409	    /**
410	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
411	     * the {@code customerCode}. Derived from stored state, never persisted.
412	     */
413	    public int getCheckDigit() {
414	        return LuhnCheckDigit.of(this.customerCode);
415	    }
416	
417	    /**
418	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
419	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
420	     */
421	    public String getContactPreference() {
422	        return hasEmail() ? "EMAIL" : "PHONE";
423	    }
424	
425	    /**
426	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
427	     * the email (or empty when absent) and the household id (or empty when none), joined by
428	     * {@code '|'}. Derived from stored state, never persisted.
429	     */
430	    public String getIdentityKey() {
431	        String emailPart = hasEmail() ? this.email : "";
432	        String householdPart = this.householdId == null ? "" : this.householdId;
433	        return this.telephone + "|" + emailPart + "|" + householdPart;
434	    }
435	
436	    private boolean hasEmail() {
437	        return this.email != null && !this.email.isEmpty();
438	    }
439	
440	    protected Set<Pet> getPetsInternal() {
441	        if (this.pets == null) {
442	            this.pets = new HashSet<>();
443	        }
444	        return this.pets;
445	    }
446	
447	    protected void setPetsInternal(Set<Pet> pets) {
448	        this.pets = pets;
449	    }
450	
451	    public List<Pet> getPets() {
452	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
453	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
454	        return Collections.unmodifiableList(sortedPets);
455	    }
456	
457	    public void setPets(List<Pet> pets) {
458	        this.pets = new HashSet<>(pets);
459	    }
460	
461	    public void addPet(Pet pet) {
462	        getPetsInternal().add(pet);
463	        pet.setOwner(this);
464	    }
465	
466	    /**
467	     * Return the Pet with the given name, or null if none found for this Owner.
468	     *
469	     * @param name to test
470	     * @return true if pet name is already in use
471	     */
472	    public Pet getPet(String name) {
473	        return getPet(name, false);
474	    }
475	
476	    /**
477	     * Return the Pet with the given name, or null if none found for this Owner.
478	     *
479	     * @param name to test
480	     * @return true if pet name is already in use
481	     */
482	    public Pet getPet(String name, boolean ignoreNew) {
483	        name = name.toLowerCase();
484	        for (Pet pet : getPetsInternal()) {
485	            if (!ignoreNew || !pet.isNew()) {
486	                String compName = pet.getName();
487	                compName = compName.toLowerCase();
488	                if (compName.equals(name)) {
489	                    return pet;
490	                }
491	            }
492	        }
493	        return null;
494	    }
495	
496	    public Pet getPet(Integer petId) {
497	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
498	    }
499	
500	    @Override
501	    public String toString() {
502	        return new ToStringCreator(this)
503	
504	            .append("id", this.getId())
505	            .append("new", this.isNew())
506	            .append("lastName", this.getLastName())
507	            .append("firstName", this.getFirstName())
508	            .append("address", this.address)
509	            .append("city", this.city)
510	            .append("telephone", this.telephone)
511	            .toString();
512	    }
513	}
