9	/**
10	 * The duplicate block: rejects a create-owner request that would be a second owner in an
11	 * existing household — same last name and postcode, and therefore the same derived
12	 * {@code householdId} (see {@link Households}) — responding 409. A request opting in with
13	 * {@code sharesHousehold} declares the new owner a genuine member of that household and
14	 * bypasses the block. An owner with no postcode has no household and is never blocked here.
15	 * Runs after {@link AssignHouseholdId} (so the household id is set) and before
16	 * {@link SaveOwner} persists a duplicate.
17	 */
18	public class EnsureUniqueHousehold {
19	
20	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
21	            throws DuplicateHouseholdException {
22	        if (owner.getHouseholdId() == null || Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        if (!Households.membersOf(ownerRepository, owner.getLastName(), owner.getPostcode()).isEmpty()) {
26	            throw new DuplicateHouseholdException(owner.getHouseholdId());
27	        }
28	    }
29	}
