1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.List;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Shared household logic. An owner belongs to a household identified by their last name
13	 * and postcode. The last name is compared case-insensitively with collapsed whitespace;
14	 * the postcode is taken verbatim (it is already validated to a canonical four-digit form).
15	 * The identifier is derived deterministically from those two fields, so every owner in the
16	 * same household resolves to the same stable value without any coordination. An owner with
17	 * no postcode has no household.
18	 */
19	final class Households {
20	
21	    private Households() {
22	    }
23	
24	    /**
25	     * The existing owners that share a household (same last name and postcode) with the
26	     * given fields. Empty when no postcode is supplied.
27	     */
28	    static List<Owner> membersOf(OwnerRepository ownerRepository, String lastName, String postcode) {
29	        String householdId = idFor(lastName, postcode);
30	        if (householdId == null) {
31	            return List.of();
32	        }
33	        return ownerRepository.findByLastName(lastName).stream()
34	                .filter(owner -> householdId.equals(idFor(owner.getLastName(), owner.getPostcode())))
35	                .toList();
36	    }
37	
38	    /**
39	     * The stable identifier shared by every owner at the given last name and postcode: the
40	     * first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' +
41	     * postcode}. Returns {@code null} when no postcode is supplied, since an owner without a
42	     * postcode has no household.
43	     */
44	    static String idFor(String lastName, String postcode) {
45	        if (postcode == null || postcode.isBlank()) {
46	            return null;
47	        }
48	        return sha256Hex(normalizeName(lastName) + "|" + postcode).substring(0, 12).toUpperCase();
49	    }
50	
51	    private static String normalizeName(String value) {
52	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
53	    }
54	
55	    private static String sha256Hex(String value) {
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder(digest.length * 2);
59	            for (byte b : digest) {
60	                sb.append(String.format("%02x", b));
61	            }
62	            return sb.toString();
63	        }
